export type Pattern = string | RegExp;
export type Attachment = 'step' | 'trajectory' | 'none';

export interface IdentityScope {
  component?: Pattern;
  route?: Pattern;
  testid?: Pattern;
  id?: Pattern;
  aria?: Pattern;
  labelledby?: Pattern;
  text?: Pattern;
  title?: Pattern;
  placeholder?: Pattern;
}

export interface IdentityRule {
  path: string;
  as: string;
  owner?: Pattern;
  scope?: IdentityScope;
  validate?: (value: unknown) => boolean;
}

export interface RouteIdentityRule {
  pattern: RegExp;
  as: string;
  validate?: (value: unknown) => boolean;
}

export interface IdentityBindings {
  trajectoryKey?: string;
  stepKey?: string;
  propRules?: IdentityRule[];
  routePatterns?: RouteIdentityRule[];
}

export interface ActionBinding {
  event?: string;
  action: string;
  semantic?: {
    schema: 'producttrace.semantic-template.v1';
    verb: string;
    object_type: string;
    object_id: string | null;
    expected_effect_type: string;
    source_event_fingerprint: string;
  };
  direction?: string;
  testid?: string;
  id?: string;
  aria?: string;
  labelledby?: string;
  text?: Pattern;
  dialog?: Pattern;
  route?: Pattern;
  title?: Pattern;
  placeholder?: Pattern;
  component?: Pattern;
  key?: Pattern;
  meta?: boolean;
  ctrl?: boolean;
  alt?: boolean;
  shift?: boolean;
  composing?: boolean;
  selection?: 'nonempty';
  /** Exact event-specific source stamp generated by producttrace/analysis. */
  sourceControl?: string;
}

export interface ProductTraceBindings {
  name: string;
  identity?: IdentityBindings;
  actions?: ActionBinding[];
  surfaces?: unknown[];
}

export interface StartOptions {
  endpoint?: string;
  onRecord?: (record: Record<string, unknown>) => void | Promise<void>;
  sink?: 'buffer';
  console?: boolean;
  maxBuffer?: number;
  outputMode?: 'operations' | 'evidence';
  operationSettleMs?: number;
  workflowIdleMs?: number;
}

export type WorkflowStatus = 'pending' | 'completed' | 'incomplete' | 'action';

export interface WorkflowCheckpoint {
  index: number;
  caption: string;
  type: 'field_change' | 'form_submit' | 'form_interaction' | 'interaction';
  surface: Record<string, unknown>;
  trigger: Record<string, unknown> | null;
  control: Record<string, unknown>;
  fields: Array<Record<string, unknown>>;
  entities: Record<string, unknown>;
  source_action: string | null;
  outcome: Record<string, unknown>;
  evidence: { ids: string[]; count: number; omitted: number };
  uncertainty: string[];
}

export interface ProductWorkflowEventRecord {
  kind: 'workflow_event';
  schema: 'producttrace.workflow-event.v1';
  event_type: 'product.workflow_started' | 'product.workflow_checkpoint' |
    'product.workflow_completed' | 'product.workflow_incomplete' | 'product.action_observed';
  event_id: string;
  timestamp: string;
  session_id: string;
  trace_id: string;
  workflow_id: string;
  source: 'producttrace.browser';
  trajectory_id: string | null;
  step_id: string | null;
  properties: {
    caption: string;
    workflow_label: string;
    workflow_status: WorkflowStatus;
    checkpoint: WorkflowCheckpoint | null;
    summary: {
      reason: string;
      steps: Array<{ index: number; caption: string; type: WorkflowCheckpoint['type'] }>;
      terminal_result_proven: boolean;
    } | null;
    entities: Record<string, unknown>;
    learning: Record<string, unknown>;
  };
  metadata: Record<string, unknown>;
}

export interface DiscoveryAnchor {
  type: string;
  value: string;
}

export interface DiscoveryIdentityCandidate {
  key: string;
  path: string;
  sample: string;
  component: string | null;
}

export interface DiscoveryEntry {
  anchor: DiscoveryAnchor;
  anchors: DiscoveryAnchor[];
  component: string | null;
  components: string[];
  events: string[];
  identity_candidates: DiscoveryIdentityCandidate[];
}

export interface DiscoveryReport {
  schema: 'producttrace.discovery.v1';
  session: string;
  enabled: boolean;
  discovery_truncated: boolean;
  count: number;
  entries: DiscoveryEntry[];
}

export interface RecorderStatus {
  session: string;
  sink: 'none' | 'endpoint' | 'onRecord' | 'buffer';
  records_delivered: number;
  records_buffered: number;
  records_dropped: number;
  sink_errors: number;
  counts: {
    total: number;
    by_kind: Record<string, number>;
    retained: number;
    commits: number;
  };
  observe_ms: { p50: number; p95: number; max: number };
  errors: number;
  consecutive_errors: number;
  drops: number;
  disabled: boolean;
  reason: string | null;
  started: boolean;
  stopped: boolean;
  hook: string;
  discover: { enabled: boolean; entries: number; truncated: boolean };
}

export interface Recorder {
  stop(): RecorderStatus;
  status(): RecorderStatus;
}

export interface ProductTraceAPI {
  start(bindings?: ProductTraceBindings, options?: StartOptions): Recorder;
  init(bindings?: ProductTraceBindings, options?: StartOptions): Recorder;
  readonly records: ReadonlyArray<Record<string, unknown>>;
  exportJSONL(): string;
  stats(): Record<string, unknown>;
  discover(enabled?: boolean): DiscoveryReport;
  discoveryReport(): DiscoveryReport;
  flush(): void;
}

export declare function start(bindings?: ProductTraceBindings, options?: StartOptions): Recorder;
export declare function stop(): RecorderStatus | null;
export declare function status(): RecorderStatus | null;
export declare function discover(enabled?: boolean): DiscoveryReport;
export declare function discoveryReport(): DiscoveryReport;
export declare const productTrace: ProductTraceAPI;
